<?php
/**
 * Export the web database to the JSON file that the Android mobile app
 * reads from Firebase Realtime Database.
 *
 * The mobile app cannot talk to MySQL directly, so MySQL stays the
 * master copy and this script mirrors the parts the app needs into a
 * single JSON document that you import into Firebase:
 *
 *   firebase/
 *   |- barangay_survey_export.json   (generated by this script)
 *   `- database.rules.json
 *
 * The bcrypt `password` column is never exported. App Inventor cannot
 * verify a bcrypt hash, so the app logs in with `mobile_pin` instead,
 * which is mirrored here in the clear.
 *
 * Usage (from the XAMPP project folder):
 *
 *   php api/export_to_firebase.php --write     rewrite the JSON file
 *   php api/export_to_firebase.php --stdout    print the JSON
 *   php api/export_to_firebase.php --push      push straight to Firebase
 *
 * Or open it in a browser for a downloadable copy:
 *
 *   http://localhost/barangay_survey/api/export_to_firebase.php
 *
 * `--push` needs the database token. Either set the FIREBASE_DB_TOKEN
 * environment variable, or create config/firebase.php containing:
 *
 *   <?php return "your-database-token";
 */

require_once __DIR__ . "/../includes/functions.php";

// Where the app reads from. Must match the FirebaseDB1 component's
// FirebaseURL in Activity_7.aia.
const FIREBASE_DB_URL = "https://activity-7-d32c8-default-rtdb.firebaseio.com";

// The file this script writes.
const EXPORT_PATH = __DIR__ . "/../firebase/barangay_survey_export.json";

/**
 * Reads the Firebase database token from the environment, falling back to
 * an optional config/firebase.php that just returns the token string.
 * Returns "" when no token is configured.
 */
function firebase_token() {
    $env = getenv("FIREBASE_DB_TOKEN");
    if ($env !== false && trim($env) !== "") {
        return trim($env);
    }

    $config = __DIR__ . "/../config/firebase.php";
    if (is_file($config)) {
        $token = include $config;
        if (is_string($token) && trim($token) !== "") {
            return trim($token);
        }
    }

    return "";
}

/** Runs a query and returns every row as an array. */
function fetch_all($conn, $sql) {
    $result = $conn->query($sql);
    if (!$result) {
        return [];
    }

    $rows = [];
    while ($row = $result->fetch_assoc()) {
        $rows[] = $row;
    }

    return $rows;
}

/**
 * Formats a timestamp or date string as "Sept 30, 2026" for the app,
 * returning "" when there is nothing to format.
 */
function export_date($value) {
    if (empty($value)) {
        return "";
    }

    try {
        return (new DateTime($value))->format("M j, Y");
    } catch (Exception $e) {
        return "";
    }
}

/**
 * Builds the whole export document.
 *
 * Residents are keyed by their Resident Number (2026-0001) rather than the
 * numeric primary key, because that is what residents type to log in on the
 * phone. Survey, question and choice ids are kept as their MySQL ids so the
 * answers coming back from the app can be matched to real rows.
 *
 * Everything is written twice, in two shapes, because the app can only walk
 * one of them. App Inventor decodes a JSON object into a dictionary, and
 * there is no block for "give me the keys of a dictionary", so a survey read
 * as an object cannot be listed on screen. Alongside the id-keyed objects
 * there are therefore ordered arrays:
 *
 *   survey_index        -> [{survey_id, title, ...}]         list of surveys
 *   surveys/1/
 *     questions         -> {"1": {...}}                      by id, for staff
 *     question_list     -> [{question_id, ..., choices_list}]  for the app
 *       choices         -> {"1": {...}}
 *       choices_list    -> [{choice_id, choice_text}]
 *
 * The duplication is deliberate and cheap: the arrays are what the phone
 * reads, the objects are what the staff pages and api/sync_responses.php
 * match answers against.
 */
function build_export($conn) {
    // ---- residents -------------------------------------------------------
    $residents = [];
    foreach (fetch_all($conn, "SELECT * FROM residents ORDER BY resident_number") as $r) {
        $residents[$r["resident_number"]] = [
            "resident_number" => $r["resident_number"],
            "first_name" => $r["first_name"] ?? "",
            "middle_name" => $r["middle_name"] ?? "",
            "last_name" => $r["last_name"] ?? "",
            "extension_name" => $r["extension_name"] ?? "",
            "full_name" => full_resident_name($r),
            "gender" => $r["gender"] ?? "",
            "civil_status" => $r["civil_status"] ?? "",
            "email" => $r["email"] ?? "",
            "contact_number" => $r["contact_number"] ?? "",
            "address" => $r["address"] ?? "",
            "birthday" => $r["birthday"] ?? "",
            "age" => $r["age"] === null ? null : (int)$r["age"],
            "occupation" => $r["occupation"] ?? "",
            "employer" => $r["employer"] ?? "",
            "spouse_name" => $r["spouse_name"] ?? "",
            "father_name" => $r["father_name"] ?? "",
            "mother_name" => $r["mother_name"] ?? "",
            // Empty when the resident has not uploaded a photo. The app
            // falls back to its bundled placeholder image.
            "photo_url" => empty($r["photo"]) ? "" : RESIDENT_PHOTO_URL . rawurlencode($r["photo"]),
            "status" => $r["status"] ?? "active",
            "is_first_login" => (bool)($r["is_first_login"] ?? 0),
            "mobile_pin" => $r["mobile_pin"] ?? "",
            "registration_date" => export_date($r["created_at"] ?? ""),
        ];
    }

    // ---- survey choices, grouped by question ----------------------------
    // Each question embeds its own choices so the app can render a whole
    // survey from a single read.
    $choices = [];
    foreach (fetch_all($conn, "SELECT * FROM survey_choices ORDER BY question_id, choice_order") as $c) {
        $choices[(int)$c["question_id"]][(string)$c["choice_id"]] = [
            "choice_id" => (int)$c["choice_id"],
            "choice_text" => $c["choice_text"],
            "choice_order" => (int)$c["choice_order"],
        ];
    }

    // ---- surveys, each with its questions --------------------------------
    $surveys = [];
    foreach (fetch_all($conn, "SELECT * FROM surveys ORDER BY survey_id") as $s) {
        $surveys[(string)$s["survey_id"]] = [
            "survey_id" => (int)$s["survey_id"],
            "title" => $s["title"],
            "description" => $s["description"] ?? "",
            "start_date" => $s["start_date"] ?? "",
            "end_date" => $s["end_date"] ?? "",
            "status" => $s["status"] ?? "active",
            "question_count" => 0,
            // Cast now, not at the end: these inner maps are keyed by ids
            // that are usually 1,2,3..., so an uncast PHP array would encode
            // as a JSON array and Firebase would renumber the keys.
            "questions" => (object) [],
            // Keyed by question id for the phone, filled in below.
            "question_list" => (object) [],
        ];
    }

    foreach (fetch_all($conn, "SELECT * FROM survey_questions ORDER BY survey_id, question_order") as $q) {
        $survey_id = (string)$q["survey_id"];
        if (!isset($surveys[$survey_id])) {
            // A question whose survey was deleted: nothing to attach it to.
            continue;
        }

        $question_id = (int)$q["question_id"];
        $question_choices = $choices[$question_id] ?? [];

        $surveys[$survey_id]["questions"]->{(string)$question_id} = [
            "question_id" => $question_id,
            "question_text" => $q["question_text"],
            "question_type" => $q["question_type"],
            "is_required" => (bool)$q["is_required"],
            "question_order" => (int)$q["question_order"],
            "choices" => (object) $question_choices,
        ];

        // The same question as an ordered map, each choice in turn.
        //
        // Every collection here is keyed by a string the phone can build,
        // and the label lists stay whole arrays. That shape is deliberate:
        // App Inventor reliably looks up a *key* in a dictionary, and handing
        // a Spinner or a ListView one pre-built list of strings is a single
        // assignment. Indexing into a list with a number is the part that is
        // easy to get wrong, so the app never has to do it.
        $surveys[$survey_id]["question_list"]->{(string)$question_id} = [
            "question_id" => $question_id,
            "question_text" => $q["question_text"],
            "question_type" => $q["question_type"],
            "is_required" => (bool)$q["is_required"],
            "question_order" => (int)$q["question_order"],
            // Hand straight to a Spinner's Elements.
            "choice_labels_list" => array_column(
                array_values($question_choices), "choice_text"
            ),
            // So the phone can tell a choice question from a typed one with
            // a number comparison, rather than measuring a list at runtime.
            "choice_count" => count($question_choices),
            // Keyed by position, so Spinner.Selection looks a choice up.
            "choices" => (object) array_combine(
                array_map(
                    function ($c) {
                        return (string) $c["choice_order"];
                    },
                    array_values($question_choices)
                ),
                array_values($question_choices)
            ),
        ];

        $surveys[$survey_id]["question_count"] = count((array) $surveys[$survey_id]["questions"]);
    }

    // ---- the same surveys as one ordered index -------------------------
    // The list screen reads only this, so it never has to walk an object.
    // Only open surveys are listed: a closed or not-yet-open survey is not
    // something a resident can answer. list_label is the finished row text
    // so ListView1.List is one assignment instead of a loop.
    $items = [];
    $labels = [];
    foreach ($surveys as $survey) {
        if ($survey["status"] !== "active") {
            continue;
        }

        $items[(string)$survey["survey_id"]] = [
            "survey_id" => $survey["survey_id"],
            "title" => $survey["title"],
            "description" => $survey["description"],
            "start_date" => $survey["start_date"],
            "end_date" => $survey["end_date"],
            "status" => $survey["status"],
            "question_count" => $survey["question_count"],
            "list_label" => trim(
                $survey["title"] . "\n"
                . ($survey["description"] !== "" ? $survey["description"] . "\n" : "")
                . $survey["question_count"] . " question"
                . ($survey["question_count"] === 1 ? "" : "s")
            ),
        ];
        $labels[] = $items[(string)$survey["survey_id"]]["list_label"];
    }

    $survey_index = [
        "count" => count($items),
        "labels" => $labels,
        "items" => (object) $items,
    ];

    return [
        "meta" => [
            "schema_version" => 2,
            "exported_at" => date("c"),
            "source" => "database/barangay_survey.sql",
            "database" => "activity-7-d32c8-default-rtdb",
            "notes" => "Generated from the web database. The bcrypt password column is deliberately NOT exported; mobile_pin is the mobile-only PIN that the Android app compares locally. survey_index, question_list and choices_list are ordered arrays for the app, which cannot read the keys of a JSON object. Regenerate with api/export_to_firebase.php instead of editing by hand.",
        ],
        "residents" => (object) $residents,
        "surveys" => (object) $surveys,
        "survey_index" => $survey_index,
        // Filled in by the app on the phone, then imported into MySQL by
        // api/sync_responses.php. Kept here so the node always exists.
        "mobile_responses" => (object) [],
    ];
}

/**
 * Encodes the payload the way Firebase expects it (UTF-8 kept readable).
 *
 * JSON_FORCE_OBJECT is deliberately NOT used here. It would encode every
 * ordered array the app relies on (survey_index, question_list,
 * choices_list) as a JSON object, which App Inventor reads as a dictionary
 * rather than a list, so the phone could not iterate them at all.
 *
 * The two hazards that flag used to prevent are handled by casting instead:
 *
 *  1. Every id-keyed map (surveys, questions, choices) is cast with
 *     (object) so it stays an object even when its ids happen to be 1,2,3.
 *     A PHP array numbered 1..5 would otherwise encode as a JSON array and
 *     Firebase would renumber those keys to 0..4, breaking every lookup.
 *  2. mobile_responses is an empty (object). An empty PHP array encodes as
 *     [], which Firebase treats as a delete, so writing `[]` there would
 *     wipe every answer the app had collected.
 */
function encode_export($payload) {
    return json_encode(
        $payload,
        JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE
    );
}

/**
 * PUTs a path to the Realtime Database using the REST API.
 * Returns a short status string.
 */
function firebase_put($path, $body, $token) {
    $url = FIREBASE_DB_URL . "/" . trim($path, "/") . ".json?auth=" . rawurlencode($token);

    if (function_exists("curl_init")) {
        $ch = curl_init($url);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_CUSTOMREQUEST => "PUT",
            CURLOPT_POSTFIELDS => $body,
            CURLOPT_HTTPHEADER => ["Content-Type: application/json"],
            CURLOPT_TIMEOUT => 30,
        ]);
        $reply = curl_exec($ch);
        $error = curl_error($ch);
        $code = curl_getinfo($ch, CURLINFO_HTTP_CODE);
        curl_close($ch);

        if ($error !== "") {
            return "error: " . $error;
        }
    } else {
        $context = stream_context_create(["http" => [
            "method" => "PUT",
            "header" => "Content-Type: application/json\r\n",
            "content" => $body,
            "timeout" => 30,
            "ignore_errors" => true,
        ]]);
        $reply = @file_get_contents($url, false, $context);
        $code = 0;
        foreach ($http_response_header ?? [] as $header) {
            if (preg_match("#^HTTP/\S+\s+(\d+)#", $header, $m)) {
                $code = (int)$m[1];
            }
        }
    }

    return "HTTP " . $code . " " . trim((string)$reply);
}

/**
 * Pushes the export to Firebase.
 *
 * Each top-level node is written separately on purpose. mobile_responses is
 * owned by the phone app, so pushing it from here would destroy answers that
 * have not been imported into MySQL yet.
 *
 * survey_index is redundant data derived from surveys, but the app reads it on
 * its own and never walks surveys, so it has to be written too.
 */
function push_to_firebase($payload, $token) {
    if ($token === "") {
        return "No token. Set FIREBASE_DB_TOKEN or create config/firebase.php.";
    }

    $lines = [];
    foreach (["meta", "residents", "surveys", "survey_index"] as $node) {
        if (!isset($payload[$node])) {
            continue;
        }

        $status = firebase_put($node, encode_export($payload[$node]), $token);
        $lines[] = "  " . str_pad($node, 18) . $status;

        if (strpos($status, "error:") === 0) {
            break;
        }
    }

    $lines[] = "  mobile_responses   left untouched (owned by the app)";
    $lines[] = "  " . count((array) $payload["residents"]) . " residents, "
        . count((array) $payload["surveys"]) . " surveys pushed.";

    return implode(PHP_EOL, $lines);
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

$payload = build_export($conn);
$json = encode_export($payload);
$mode = (php_sapi_name() === "cli" && isset($argv[1])) ? $argv[1] : "--download";

if ($mode === "--stdout") {
    echo $json . PHP_EOL;
    exit(0);
}

if ($mode === "--write") {
    $dir = dirname(EXPORT_PATH);
    if (!is_dir($dir)) {
        mkdir($dir, 0755, true);
    }
    if (file_put_contents(EXPORT_PATH, $json . PHP_EOL) === false) {
        fwrite(STDERR, "Could not write " . EXPORT_PATH . PHP_EOL);
        exit(1);
    }
    echo "Wrote " . EXPORT_PATH . PHP_EOL;
    echo count((array) $payload["residents"]) . " residents, "
        . count((array) $payload["surveys"]) . " surveys." . PHP_EOL;
    echo "Import it into Firebase, or re-run with --push." . PHP_EOL;
    exit(0);
}

if ($mode === "--push") {
    echo push_to_firebase($payload, firebase_token()) . PHP_EOL;
    exit(0);
}

// Browser: hand over the file as a download.
header("Content-Type: application/json; charset=utf-8");
header("Content-Disposition: attachment; filename=\"barangay_survey_export.json\"");
echo $json;
